SELECT COUNT_BIG(*) AS relaciones_inconsistentes FROM dbo.ProductosServiciosVarianteValores v JOIN dbo.ProductosServiciosVariantes pv ON pv.id=v.idVariante AND pv.idEmpresa=v.idEmpresa JOIN dbo.ProductosServiciosOpcionesVariante ov ON ov.id=v.idOpcionVariante AND ov.idEmpresa=v.idEmpresa JOIN dbo.ProductosServiciosOpcionesVarianteValores ovv ON ovv.id=v.idOpcionVarianteValor AND ovv.idEmpresa=v.idEmpresa WHERE ov.idProductoServicio<>pv.idProductoServicio OR ovv.idOpcionVariante<>ov.id